using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;using Newtonsoft.Json;using Newtonsoft.Json.Linq;
public static class B1CleanApply {
 static string R=>Path.GetFullPath(Path.Combine(Application.dataPath,"../../.."));static string H=>R+"/SourceAssets/B1_FullFloor/";
 static string Key(Mesh m){AssetDatabase.TryGetGUIDAndLocalFileIdentifier(m,out string g,out long id);return g+"_"+id;}
 public static object Run(){var s=SceneManager.GetActiveScene();if(s.isDirty||Application.isPlaying||!s.path.EndsWith("Level_B1_Circular.unity"))throw new Exception("Saved B1 only");AssetDatabase.Refresh(ImportAssetOptions.ForceSynchronousImport);var root=GameObject.Find("B1_ResearchAndStaffFloor");var data=JArray.Parse(File.ReadAllText(H+"clean_models.json"));var map=new Dictionary<string,(Mesh mesh,int[] slots)>();var records=new List<object>();
  foreach(var q in data){string p=(string)q["asset"];var importer=(ModelImporter)AssetImporter.GetAtPath(p);importer.importAnimation=false;importer.isReadable=false;importer.importNormals=ModelImporterNormals.Import;importer.importTangents=ModelImporterTangents.CalculateMikk;importer.materialImportMode=ModelImporterMaterialImportMode.ImportStandard;importer.materialLocation=ModelImporterMaterialLocation.InPrefab;importer.SaveAndReimport();var src=AssetDatabase.LoadAssetAtPath<GameObject>(p).GetComponentsInChildren<MeshFilter>().Single();var slots=src.GetComponent<MeshRenderer>().sharedMaterials.Select(m=>int.Parse(m.name.Split('_').Last())).ToArray();map[(string)q["sourceMesh"]]=(src.sharedMesh,slots);}
  foreach(var mf in root.GetComponentsInChildren<MeshFilter>()){if(!mf.sharedMesh||!map.TryGetValue(Key(mf.sharedMesh),out var dest))continue;var old=mf.sharedMesh;float error=(dest.mesh.bounds.center-old.bounds.center).magnitude+(dest.mesh.bounds.size-old.bounds.size).magnitude;if(error>.005f)throw new Exception("Bounds mismatch "+old.name+" "+error);var rr=mf.GetComponent<MeshRenderer>();var ms=rr.sharedMaterials;rr.sharedMaterials=dest.slots.Select(i=>ms[i]).ToArray();mf.sharedMesh=dest.mesh;records.Add(new{objectName=mf.name,source=old.name,asset=AssetDatabase.GetAssetPath(dest.mesh),boundsError=error});}
  var gscan=JObject.Parse(File.ReadAllText(H+"geometry_scan/Level_B1_Circular.json"));var moved=new HashSet<Transform>();foreach(var q in gscan["overlaps"]){var a=gscan["rows"][(int)q["a"]];var b=gscan["rows"][(int)q["b"]];if((string)b["meshName"]!="CCTV_Fixed_Rubber"||(string)a["meshName"]!="CCTV_Fixed_Housing")continue;GlobalObjectId.TryParse((string)b["id"],out var gid);var rr=GlobalObjectId.GlobalObjectIdentifierToObjectSlow(gid) as MeshRenderer;if(rr&&moved.Add(rr.transform)){var normal=new Vector3((float)q["normal"][0],(float)q["normal"][1],(float)q["normal"][2]);rr.transform.position+=normal*.0012f;}}
  var steel=AssetDatabase.LoadAssetAtPath<Material>("Assets/Afrer_Seconds/05.Model/Environment/B1/Materials/B1M_Steel.mat");int supports=0;foreach(var t in root.GetComponentsInChildren<Transform>().Where(t=>t.name.Contains("DoubleWashSink")&&t.parent&&t.parent.name=="Equipment")){foreach(float x in new[]{-.81f,.81f})foreach(float z in new[]{-.285f,.285f}){var go=GameObject.CreatePrimitive(PrimitiveType.Cylinder);go.name="B1_SinkSupport";go.transform.SetParent(t,false);go.transform.localPosition=new Vector3(x,.51f,z);go.transform.localScale=new Vector3(.038f,.35f,.038f);UnityEngine.Object.DestroyImmediate(go.GetComponent<Collider>());go.GetComponent<Renderer>().sharedMaterial=steel;supports++;}}
  foreach(var t in root.GetComponentsInChildren<Transform>(true))if(PrefabUtility.IsPartOfPrefabInstance(t)){PrefabUtility.RecordPrefabInstancePropertyModifications(t);foreach(var c in t.GetComponents<Component>())if(c)PrefabUtility.RecordPrefabInstancePropertyModifications(c);}Physics.SyncTransforms();EditorSceneManager.MarkSceneDirty(s);EditorSceneManager.SaveScene(s);AssetDatabase.SaveAssets();File.WriteAllText(H+"clean_applied.json",JsonConvert.SerializeObject(new{records,cameraGaskets=moved.Count,sinkSupports=supports,collidersPreserved=true},Formatting.Indented));return new{renderers=records.Count,cameraGaskets=moved.Count,sinkSupports=supports};
 }
}
